-- Recorded activity, not debate duration or a legislative result.
CREATE TABLE public.parliament_activity (
 id text PRIMARY KEY CHECK (id ~ '^[a-f0-9]{64}$'),
 legislature integer NOT NULL CHECK (legislature=15),
 topic text NOT NULL CHECK(topic='housing'),
 event_date date NOT NULL,
 initiative_number text NOT NULL,
 title text NOT NULL,
 initiative_type text NOT NULL,
 kind text NOT NULL CHECK(kind IN ('intervention','voting_record')),
 body text,phase text,speaker text,speaker_role text,proposer_label text,
 documents jsonb NOT NULL CHECK(jsonb_typeof(documents)='array' AND jsonb_array_length(documents)>0),
 title_signal text NOT NULL,
 mapping_version text NOT NULL CHECK(mapping_version='housing-title-words-v1'),
 dataset_sha256 text NOT NULL CHECK(dataset_sha256 ~ '^[a-f0-9]{64}$'),
 politician_id uuid REFERENCES politicians(id) ON DELETE SET NULL,
 official_id uuid REFERENCES public_officials(id) ON DELETE SET NULL
);
CREATE INDEX parliament_activity_date ON public.parliament_activity(event_date DESC,id);
ALTER TABLE public.parliament_activity ENABLE ROW LEVEL SECURITY;
CREATE POLICY parliament_activity_read ON public.parliament_activity FOR SELECT TO anon,authenticated USING(true);
GRANT SELECT ON public.parliament_activity TO anon,authenticated;
GRANT ALL ON public.parliament_activity TO service_role;
CREATE TABLE public.parliament_activity_coverage (
 scope text PRIMARY KEY CHECK(scope='congreso-15-housing'),metadata jsonb NOT NULL
);
ALTER TABLE public.parliament_activity_coverage ENABLE ROW LEVEL SECURITY;
CREATE POLICY parliament_activity_coverage_read ON public.parliament_activity_coverage FOR SELECT TO anon,authenticated USING(true);
GRANT SELECT ON public.parliament_activity_coverage TO anon,authenticated;
GRANT ALL ON public.parliament_activity_coverage TO service_role;
